from z3 import *

# Parameters
num_golfers = 30
num_weeks = 7
num_groups = 10

# Variables: group[w][p] in 0..9
grp = [[Int(f'g_{w}_{p}') for p in range(num_golfers)] for w in range(num_weeks)]

s = Solver()

# Domain constraints
for w in range(num_weeks):
    for p in range(num_golfers):
        s.add(grp[w][p] >= 0, grp[w][p] < num_groups)

# Each week, each group has exactly 3 golfers
for w in range(num_weeks):
    for g in range(num_groups):
        s.add(Sum([If(grp[w][p] == g, 1, 0) for p in range(num_golfers)]) == 3)

# No pair meets more than once
for i in range(num_golfers):
    for j in range(i+1, num_golfers):
        s.add(Sum([If(grp[w][i] == grp[w][j], 1, 0) for w in range(num_weeks)]) <= 1)

print("Constraints added, solving...")
res = s.check()
print(res)

if res == sat:
    m = s.model()
    result = []
    for w in range(num_weeks):
        for p in range(num_golfers):
            result.append(int(str(m.evaluate(grp[w][p]))))

    print("Result length:", len(result))
    print(result)

    # Verify the solution
    for w in range(num_weeks):
        groups = [[] for _ in range(num_groups)]
        for p in range(num_golfers):
            g = result[w*30 + p]
            groups[g].append(p)
        print(f"Week {w}: group sizes = {[len(g) for g in groups]}")

    pair_counts = {}
    max_meet = 0
    for w in range(num_weeks):
        for g in range(num_groups):
            members = [p for p in range(num_golfers) if result[w*30 + p] == g]
            for i in range(len(members)):
                for j in range(i+1, len(members)):
                    pair = tuple(sorted((members[i], members[j])))
                    pair_counts[pair] = pair_counts.get(pair, 0) + 1
                    max_meet = max(max_meet, pair_counts[pair])

    print(f"Max pair meetings: {max_meet}")
    print(f"Unique pairs: {len(pair_counts)}")
